BEGIN;
CREATE OR REPLACE FUNCTION safety_change_reject_mutation() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'safety change quorum history is immutable'; END $$;
CREATE TABLE IF NOT EXISTS safety_change_scopes (scope_hash text PRIMARY KEY CHECK(scope_hash ~ '^[a-f0-9]{64}$'),operator_test_id text NOT NULL,tenant_fingerprint text NOT NULL,scope_id text NOT NULL,payload jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(operator_test_id,tenant_fingerprint,scope_id));
CREATE TABLE IF NOT EXISTS safety_change_policy_snapshots (scope_hash text NOT NULL REFERENCES safety_change_scopes(scope_hash),policy_hash text PRIMARY KEY CHECK(policy_hash ~ '^[a-f0-9]{64}$'),payload jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS safety_change_class_snapshots (scope_hash text NOT NULL REFERENCES safety_change_scopes(scope_hash),class_hash text PRIMARY KEY CHECK(class_hash ~ '^[a-f0-9]{64}$'),payload jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS safety_change_requests (scope_hash text NOT NULL REFERENCES safety_change_scopes(scope_hash),request_hash text PRIMARY KEY CHECK(request_hash ~ '^[a-f0-9]{64}$'),payload jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS safety_change_qualification_evidence (scope_hash text NOT NULL REFERENCES safety_change_scopes(scope_hash),evidence_hash text PRIMARY KEY CHECK(evidence_hash ~ '^[a-f0-9]{64}$'),payload jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS safety_change_approval_attestations (scope_hash text NOT NULL REFERENCES safety_change_scopes(scope_hash),approval_hash text PRIMARY KEY CHECK(approval_hash ~ '^[a-f0-9]{64}$'),payload jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS safety_change_quorum_decisions (scope_hash text NOT NULL REFERENCES safety_change_scopes(scope_hash),decision_hash text PRIMARY KEY CHECK(decision_hash ~ '^[a-f0-9]{64}$'),payload jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS safety_change_apply_receipts (scope_hash text NOT NULL REFERENCES safety_change_scopes(scope_hash),receipt_hash text PRIMARY KEY CHECK(receipt_hash ~ '^[a-f0-9]{64}$'),payload jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS safety_change_break_glass_leases (scope_hash text NOT NULL REFERENCES safety_change_scopes(scope_hash),lease_hash text PRIMARY KEY CHECK(lease_hash ~ '^[a-f0-9]{64}$'),payload jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS safety_change_break_glass_use_receipts (scope_hash text NOT NULL REFERENCES safety_change_scopes(scope_hash),receipt_hash text PRIMARY KEY CHECK(receipt_hash ~ '^[a-f0-9]{64}$'),payload jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS safety_change_break_glass_revocation_receipts (scope_hash text NOT NULL REFERENCES safety_change_scopes(scope_hash),receipt_hash text PRIMARY KEY CHECK(receipt_hash ~ '^[a-f0-9]{64}$'),payload jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS safety_change_transitions (scope_hash text NOT NULL REFERENCES safety_change_scopes(scope_hash),transition_hash text PRIMARY KEY CHECK(transition_hash ~ '^[a-f0-9]{64}$'),payload jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS safety_change_conflicts (scope_hash text NOT NULL REFERENCES safety_change_scopes(scope_hash),conflict_hash text PRIMARY KEY CHECK(conflict_hash ~ '^[a-f0-9]{64}$'),payload jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS safety_change_request_claims (operator_test_id text NOT NULL,idempotency_key text NOT NULL,request_hash text NOT NULL CHECK(request_hash ~ '^[a-f0-9]{64}$'),scope_hash text NOT NULL REFERENCES safety_change_scopes(scope_hash),payload jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(operator_test_id,idempotency_key));
CREATE TABLE IF NOT EXISTS safety_change_test_center_bundles (run_id text PRIMARY KEY REFERENCES agent_test_center_runs(run_id),scope_hash text NOT NULL REFERENCES safety_change_scopes(scope_hash),decision_hash text NOT NULL REFERENCES safety_change_quorum_decisions(decision_hash),created_at timestamptz NOT NULL DEFAULT now());
DO $$ DECLARE item text; BEGIN FOREACH item IN ARRAY ARRAY['safety_change_scopes','safety_change_policy_snapshots','safety_change_class_snapshots','safety_change_requests','safety_change_qualification_evidence','safety_change_approval_attestations','safety_change_quorum_decisions','safety_change_apply_receipts','safety_change_break_glass_leases','safety_change_break_glass_use_receipts','safety_change_break_glass_revocation_receipts','safety_change_transitions','safety_change_conflicts','safety_change_request_claims','safety_change_test_center_bundles'] LOOP EXECUTE format('DROP TRIGGER IF EXISTS %I_immutable ON %I',item,item); EXECUTE format('CREATE TRIGGER %I_immutable BEFORE UPDATE OR DELETE ON %I FOR EACH ROW EXECUTE FUNCTION safety_change_reject_mutation()',item,item); END LOOP; END $$;
COMMIT;
